code_sketch:
static readonly ThreadLocal<RequestContext> Current =
    new ThreadLocal<RequestContext>(() => new RequestContext());

app.Use((context, next) =>
{
    Current.Value = RequestContext.For(context);   // this thread's copy, built on first use
    try { return next(); }
    finally { Current.Value = null; }              // pooled thread: never leak the caller
});

